-- COMMAND ----------

CREATE SCHEMA IF NOT EXISTS genie_course_hr;
USE SCHEMA genie_course_hr;

-- COMMAND ----------

-- DBTITLE 1,Compensation
-----------------------------------
-- Create compensation table
-----------------------------------
CREATE TABLE IF NOT EXISTS compensation (
  employee_id STRING NOT NULL,
  base_salary INT,
  market_benchmark INT,
  comp_ratio DOUBLE,
  last_raise_date DATE,
  last_raise_pct DOUBLE
);

-- Insert data only if table is empty
BEGIN
  DECLARE row_count INT;
  SET row_count = (SELECT COUNT(*) FROM compensation);
  IF row_count = 0 THEN
    SET row_count = (SELECT COUNT(*) FROM compensation);
    SELECT 'compensation: Inserted ' || row_count || ' rows.' AS status;
  ELSE
    SELECT 'compensation: Table already has ' || row_count || ' rows. Skipping insert.' AS status;
  END IF;
END;

-- COMMAND ----------

-- DBTITLE 1,Employees
-- Create employees table
CREATE TABLE IF NOT EXISTS employees (
  employee_id STRING NOT NULL,
  first_name STRING,
  last_name STRING,
  department STRING,
  region STRING,
  hire_date DATE,
  manager_id STRING,
  job_title STRING,
  job_level INT,
  status STRING
);

-- Insert data only if table is empty
BEGIN
  DECLARE row_count INT;
  SET row_count = (SELECT COUNT(*) FROM employees);
  IF row_count = 0 THEN
    SET row_count = (SELECT COUNT(*) FROM employees);
    SELECT 'employees: Inserted ' || row_count || ' rows.' AS status;
  ELSE
    SELECT 'employees: Table already has ' || row_count || ' rows. Skipping insert.' AS status;
  END IF;
END;

